Everything Latin", "purpose": null, "t": [["65H6t1WQBim6q93yM8fEwn", "Obsesion", "Aventura, Judy Santos"], ["7mWFF4gPADjTQjC97CgFVt", "Baila Baila Baila - Remix", "Ozuna, Daddy Yankee, J Balvin, Farruko, Anuel AA"], ["3G7agPwWfcORnWCAGMDOpm", "LA MuDANZA", "Bad Bunny"], ["6JjPBQfI2Y8nIjnm65X6Pw", "X (feat. Maluma & Ozuna) - Remix", "Nicky Jam, J Balvin, Maluma, Ozuna"], ["7JIjUx3GsL0upxmNJacmtz", "Suavemente", "Elvis Crespo"], ["6osaMSJh9NguagEDQcZaKx", "Loco Contigo (feat. J. Balvin & Tyga)", "DJ Snake, J Balvin, Tyga"], ["5w9c2J52mkdntKOmRLeM2m", "Con Calma", "Daddy Yankee, Snow"], ["6mICuAdrwEjh6Y6lroV2Kg", "Chantaje (feat. Maluma)", "Shakira, Maluma"], ["1EYep4FjeAIjklSNgAATX0", "Vente Pa' Ca (feat. Maluma)", "Ricky Martin, Maluma"], ["3ZFTkvIE7kyPt6Nu3PEa7V", "Hips Don't Lie (feat. Wyclef Jean)", "Shakira, Wyclef Jean"], ["3iB8eciGU9vZkaDYkz7Ir9", "Bamboléo", "Gipsy Kings"], ["6VNXmo59yDYgcwLS17UNAW", "CAFé CON RON", "Bad Bunny, Los Pleneros de la Cresta"], ["2lTm559tuIvatlT1u0JYG2", "BAILE INoLVIDABLE", "Bad Bunny"], ["6PSKhwo0mVcOdjUOhVJd5p", "Bailando - Spanish Version", "Enrique Iglesias, Descemer Bueno, Gente De Zona"], ["1IHWl5LamUGEuP4ozKQSXZ", "Tití Me Preguntó", "Bad Bunny"], ["3pDhN3qB33AOPhQEkUCaWt", "Limbo", "Daddy Yankee"], ["3sK8wGT43QFpWrvNQsrQya", "DtMF", "Bad Bunny"], ["228BxWXUYQPJrJYHDLOHkj", "Gasolina", "Daddy Yankee"], ["7qCAVkHWZkF44OzOUKf8Cr", "El Perdón (with Enrique Iglesias)", "Nicky Jam, Enrique Iglesias"], ["5fwSHlTEWpluwOM0Sxnh5k", "Pepas", "Farruko"], ["4Ol5zkXC0ouCecmLmTK6Xb", "Ginza", "J Balvin"], ["5adqS3stLaSPAEOszOnpXG", "DUELE EL CORAZON", "Enrique Iglesias, Wisin"], ["1RouRzlg8OKFeqc6LvdxmB", "Felices los 4", "Maluma"], ["5cepAtqnEQ6yVG6088zMMu", "Corazón (feat. Nego do Borel)", "Maluma, Nego do Borel"], ["3X5M53Xi5k1SijRtZMM3TA", "Te Boté - Remix", "Nio Garcia, Casper Magico, Bad Bunny, Darell, Ozuna, Nicky Jam"]]}]$J$::jsonb;
  p jsonb; pid uuid; k int := 0;
begin
  for p in select * from jsonb_array_elements(doc) loop
    k := k + 1;
    insert into public.playlists (company_id, kind, title, purpose, status, spotify_playlist_id, synced_at, created_by, created_at)
    values (c, 'editorial', p->>'name', p->>'purpose', 'published', p->>'id', now(), adm, now() - make_interval(mins => 100 - k))
    on conflict (company_id, spotify_playlist_id) do update set title = excluded.title, purpose = excluded.purpose
    returning id into pid;
    insert into public.artists (company_id, name) select distinct c, x->>2 from jsonb_array_elements(p->'t') x on conflict (company_id, name) do nothing;
    insert into public.music_tracks (company_id, title, artist_id, provider, provider_track_id, external_url, artwork_url, rights_status, status)
    select c, x->>1, ar.id, 'spotify', x->>0, 'https://open.spotify.com/track/' || (x->>0), 'https://i.scdn.co/image/' || (x->>0), 'metadata_only', 'published'
    from jsonb_array_elements(p->'t') x join public.artists ar on ar.company_id = c and ar.name = x->>2
    on conflict (company_id, provider, provider_track_id) do nothing;
    delete from public.playlist_tracks where playlist_id = pid;
    insert into public.playlist_tracks (playlist_id, track_id, position)
    select pid, mt.id, (min(o) - 1)::int from jsonb_array_elements(p->'t') with ordinality as e(x, o)
    join public.music_tracks mt on mt.company_id = c and mt.provider = 'spotify' and mt.provider_track_id = x->>0
    group by mt.id;
  end loop;
end $do$;
